-- Same readings as bot.moderation._variants: folded, punctuation read as
-- letters, and padding runs (aaa) squeezed.
create or replace function public.dm_variants(t text)
returns text[] language plpgsql immutable set search_path = '' as $$
declare base text; res text[] := '{}'; v text;
begin
  base := regexp_replace(coalesce(t, ''), '[\u200b\u200c\u200d\u200e\u200f\u2060\ufeff\u00ad]', '', 'g');
  base := normalize(base, NFKD);
  base := regexp_replace(base, '[\u0300-\u036f\u1ab0-\u1aff\u1dc0-\u1dff\u20d0-\u20ff\ufe20-\ufe2f]', '', 'g');
  base := lower(base);
  base := replace(base, 'ß', 'ss');
  base := replace(replace(replace(replace(base, 'œ', 'oe'), 'æ', 'ae'), 'ß', 'ss'), 'þ', 'th');
  base := translate(base, '013456789øðαεικορτυχавекмнорстух', 'oieasgtbgodaeikoptuxabekmhopctyx');
  res := array[base];
  v := translate(base, '@$!|¡£€+([{<*', 'asiiiletccccx');
  if v <> all(res) then res := res || v; end if;
  foreach v in array res loop
    v := regexp_replace(v, '(.)\1{2,}', '\1', 'g');
    if v <> all(res) then res := res || v; end if;
  end loop;
  return res;
end $$;

-- True when the text breaks the content rules (same answer as bot.moderation.evaluate).
create or replace function public.dm_bad_text(t text)
returns boolean language plpgsql stable security definer set search_path = '' as $$
declare r text[] := public.dm_variants(t); c text[] := '{}'; v text;
begin
  if coalesce(btrim(t), '') = '' then return false; end if;
  foreach v in array r loop
    v := regexp_replace(v, '(.)\1+', '\1', 'g');
    if v <> all(r) and v <> all(c) then c := c || v; end if;
  end loop;
  return exists (select 1 from public.dm_filter f, unnest(r) h where f.kind = 'text' and h ~ f.pattern)
      or exists (select 1 from public.dm_filter f, unnest(c) h where f.kind = 'collapsed' and h ~ f.pattern);
end $$;
revoke all on function public.dm_variants(text) from public, anon;
revoke all on function public.dm_bad_text(text) from public, anon;
grant execute on function public.dm_bad_text(text) to authenticated;
